/**
 * The private Connect card's Connected and Cancel clicks. Each starts the
 * clicker's next turn in the card's thread.
 */
import { isRecord } from "../../internal/is-record.js";
export const SLACK_CONNECT_DONE_ACTION_ID = "agent_serve_connect_done";
export const SLACK_CONNECT_CANCEL_ACTION_ID = "agent_serve_connect_cancel";
export function parseConnectAction(actionId, raw) {
    const decision = actionId === SLACK_CONNECT_DONE_ACTION_ID
        ? "approve"
        : actionId === SLACK_CONNECT_CANCEL_ACTION_ID
            ? "deny"
            : null;
    if (decision === null) {
        return null;
    }
    try {
        const value = JSON.parse(raw);
        if (!isRecord(value) ||
            typeof value.threadTs !== "string" ||
            typeof value.connection !== "string" ||
            value.threadTs === "" ||
            value.connection === "") {
            return null;
        }
        return { threadTs: value.threadTs, connection: value.connection, decision };
    }
    catch {
        return null;
    }
}
